import { Mongo } from 'meteor/mongo';
import { Session } from 'meteor/session';
import { Dapple, web3Obj } from 'meteor/makerotc:dapple';
import { convertTo18Precision } from '/imports/utils/conversion';

class TokensCollection extends Mongo.Collection {
  /**
   * Syncs the quote and base currencies' balances and allowances of selected account,
   * usually called for each new block
   */
  sync() {
    const network = Session.get('network');
    const address = web3Obj.eth.defaultAccount;
    if (address) {
      web3Obj.eth.getBalance(address, (error, balance) => {
        const newETHBalance = balance.toString(10);
        if (!error && !Session.equals('ETHBalance', newETHBalance)) {
          Session.set('ETHBalance', newETHBalance);
        }
      });

      // Get GNTBalance
      // XXX EIP20
      Dapple.getToken('GNT', (error, token) => {
        if (!error) {
          token.balanceOf(address, (callError, balance) => {
            const newGNTBalance = balance.toString(10);
            if (!error && !Session.equals('GNTBalance', newGNTBalance)) {
              Session.set('GNTBalance', newGNTBalance);
            }
          });
          const broker = Session.get('GNTBroker');
          if (typeof broker === 'undefined' || broker === '0x0000000000000000000000000000000000000000') {
            Session.set('GNTBrokerBalance', 0);
          } else {
            token.balanceOf(broker, (callError, balance) => {
              if (!callError) {
                const newGNTBrokerBalance = balance.toString(10);
                Session.set('GNTBrokerBalance', newGNTBrokerBalance);
              }
            });
          }
        }
      });

      // const ALL_TOKENS = _.uniq([Session.get('quoteCurrency'), Session.get('baseCurrency')]);
      const ALL_TOKENS = Dapple.getTokens();

      if (network !== 'private') {
        // Sync token balances and allowances asynchronously
        ALL_TOKENS.forEach((tokenId) => {
          // XXX EIP20
          Dapple.getToken(tokenId, (error, token) => {
            if (!error) {
              token.balanceOf(address, (callError, balance) => {
                if (!error) {
                  super.upsert(tokenId, { $set: {
                    balance: convertTo18Precision(balance, tokenId).toString(10),
                    realBalance: balance.toString(10),
                  } });
                  Session.set('balanceLoaded', true);
                  if (tokenId === 'W-GNT') {
                    /**
                     * https://github.com/makerdao/token-wrapper/blob/master/src/wrapper.sol#L63
                     *
                     * Basically the argument is not used but since some changes in web3
                     * https://github.com/ethereum/web3.js/pull/866/commits/77da88a6718cf6eeb45e470104f95b8832f30e34
                     *
                     * which enforces you to use all arguments of a given method,
                     * we pass arbitrary address in order to circumvent the issue.
                     *
                     * Usage of Session.get('address') has NO MEANING whatsoever.
                     */
                    token.getBroker.call(Session.get('address'), (e, broker) => {
                      if (!e) {
                        super.upsert('W-GNT', { $set: { broker } });
                        Session.set('GNTBroker', broker);
                      }
                    });
                  }
                }
              });
              const contractAddress = Dapple['maker-otc'].environments[Dapple.env].otc.value;
              token.allowance(address, contractAddress, (callError, allowance) => {
                if (!error) {
                  super.upsert(tokenId, { $set: {
                    allowance: convertTo18Precision(allowance, tokenId).toString(10),
                    realAllowance: allowance.toString(10),
                  } });
                  Session.set('allowanceLoaded', true);
                }
              });
            }
          });
        });
      } else {
        ALL_TOKENS.forEach((token) => {
          super.upsert(token, { $set: { balance: '0', allowance: '0' } });
        });
      }
    }
  }
}

export default new TokensCollection(null);

import { Meteor } from 'meteor/meteor';
import { Session } from 'meteor/session';
import Transactions from './transactions';

class WETH {
  watchDeposit() {
    Transactions.observeRemoved('ethtokens_deposit', (document) => {
      if (document.receipt.logs.length === 0) {
        Session.set('ETHDepositProgress', 0);
        Session.set('ETHDepositProgressMessage', '');
        Session.set('ETHDepositErrorMessage', 'Wrap went wrong. Please execute the wrap again.');
      } else {
        Session.set('ETHDepositProgress', 100);
        Session.set('ETHDepositProgressMessage', 'Wrap Done!');
        Meteor.setTimeout(() => {
          Session.set('ETHDepositProgress', 0);
          Session.set('ETHDepositProgressMessage', '');
        }, 10000);
      }
    });
  }

  watchWithdraw() {
    Transactions.observeRemoved('ethtokens_withdraw', (document) => {
      if (document.receipt.logs.length === 0) {
        Session.set('ETHWithdrawProgress', 0);
        Session.set('ETHWithdrawProgressMessage', '');
        Session.set('ETHWithdrawErrorMessage', 'Unwrapping went wrong. Please execute the withdraw again.');
      } else {
        Session.set('ETHWithdrawProgress', 100);
        Session.set('ETHWithdrawProgressMessage', 'Unwrap Done!');
        Meteor.setTimeout(() => {
          Session.set('ETHWithdrawProgress', 0);
          Session.set('ETHWithdrawProgressMessage', '');
        }, 10000);
      }
    });
  }
}

export default new WETH();

import { Mongo } from 'meteor/mongo';
import { Session } from 'meteor/session';
import { Dapple, web3Obj } from 'meteor/makerotc:dapple';
import { convertTo18Precision } from '/imports/utils/conversion';

class TokenEventCollection extends Mongo.Collection {
  fromLabel() {
    return this.from;
  }

  toLabel() {
    return super.to;
  }

  setEventLoadingIndicatorStatus(txhash, status) {
    const currentlyLoading = Session.get('loadingTokenEvents') || {};
    currentlyLoading[txhash] = status;
    Session.set('loadingTokenEvents', currentlyLoading);
  }

  getLatestBlock() {
    return new Promise((resolve, reject) => {
      web3Obj.eth.getBlock('latest', (blockError, block) => {
        if (!blockError) {
          resolve(block);
        } else {
          reject(blockError);
        }
      });
    });
  }

  prepareRow(tokenId, event) {
    const row = {
      blockNumber: event.blockNumber,
      transactionHash: event.transactionHash,
      timestamp: null,
      token: tokenId,
      type: event.event.toLowerCase(),
    };
    // Handle different kinds of contract events
    switch (row.type) {
      case 'transfer':
        row.from = event.args.from;
        row.to = event.args.to;
        row.amount = convertTo18Precision(event.args.value, Dapple.getTokenByAddress(event.address));
        break;
      case 'deposit':
        row.from = event.args.who;
        row.to = event.address;
        row.amount = convertTo18Precision(event.args.amount, Dapple.getTokenByAddress(event.address));
        break;
      case 'withdrawal':
        row.from = event.address;
        row.to = event.args.who;
        row.amount = convertTo18Precision(event.args.amount, Dapple.getTokenByAddress(event.address));
        break;
      default:
        break;
    }
    // Convert amount to string for storage
    if (typeof (row.amount) !== 'undefined') {
      row.amount = row.amount.toString(10);
    }

    return row;
  }

  syncEvent(tokenId, event) {
    const row = this.prepareRow(tokenId, event);
    super.insert(row);
  }

  syncEvents(tokenId, events) {
    const rows = [];
    for (let i = 0; i < events.length; i++) {
      rows[i] = this.prepareRow(tokenId, events[i]);
    }
    super.batchInsert(rows, () => {});
  }

  syncTimestamps() {
    const open = super.find({ timestamp: null }).fetch();
    // Sync all open transactions non-blocking and asynchronously
    const syncTs = (index) => {
      // console.log('syncing ts', index);
      if (index >= 0 && index < open.length) {
        web3Obj.eth.getBlock(open[index].blockNumber, (error, result) => {
          if (!error) {
            // console.log('update', open[index].blockNumber, result.timestamp);
            super.update({ blockNumber: open[index].blockNumber },
              { $set: { timestamp: result.timestamp } }, { multi: true });
            this.setEventLoadingIndicatorStatus(open[index].transactionHash, false);
          }
          syncTs(index + 1);
        });
      }
    };
    syncTs(0);
  }

  watchEvents() {
    if (Session.get('AVGBlocksPerDay') && !Session.get('watchedEvents')) {
      Session.set('watchedEvents', true);
      const self = this;
      self.getLatestBlock().then((block) => {
        self.watchTokenEvents(block.number);
        self.watchGNTTokenEvents(block.number);
      });
    }
  }

  /* eslint new-cap: ["error", { "capIsNewExceptions": ["Transfer", "Deposit", "Withdrawal"] }] */

  watchTokenEvents(latestBlock) {
    // console.log('filtering token events from ', Session.get('startBlock'));
    const ALL_TOKENS = Dapple.getTokens();
    ALL_TOKENS.forEach((tokenId) => {
      Dapple.getToken(tokenId, (error, token) => {
        // console.log(tokenId);
        if (!error) {
          const address = Session.get('address');
          const self = this;
          // TODO: extract duplicated logic for every event in separate abstraction layer
          token.Transfer({ from: address }, {
            fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
          }).get((err, result) => {
            if (!err) {
              self.syncEvents(tokenId, result);
              result.forEach((transferEvent) => {
                this.setEventLoadingIndicatorStatus(transferEvent.transactionHash, true);
              });
              Session.set('loadingTransferHistory', false);
            }
            token.Transfer({ from: address }, { fromBlock: 'latest' }, (err2, result2) => {
              if (!err2) {
                this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                self.syncEvent(tokenId, result2);
              }
            });
          });

          token.Transfer({ to: address }, {
            fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
          }).get((err, result) => {
            if (!err) {
              self.syncEvents(tokenId, result);
              result.forEach((transferEvent) => {
                this.setEventLoadingIndicatorStatus(transferEvent.transactionHash, true);
              });
              Session.set('loadingTransferHistory', false);
            }
            token.Transfer({ to: address }, { fromBlock: 'latest' }, (err2, result2) => {
              if (!err2) {
                this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                self.syncEvent(tokenId, result2);
              }
            });
          });
          if (tokenId === 'W-ETH') {
            token.Deposit({who: address}, {
              fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
            }).get((err, result) => {
              if (!err) {
                self.syncEvents(tokenId, result);
                result.forEach((depositEvent) => {
                  this.setEventLoadingIndicatorStatus(depositEvent.transactionHash, true);
                });
                Session.set('loadingWrapHistory', false);
              }
              token.Deposit({who: address}, { fromBlock: 'latest' }, (err2, result2) => {
                if (!err2) {
                  this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                  self.syncEvent(tokenId, result2);
                }
              });
            });
            token.Withdrawal({who: address}, {
              fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
            }).get((err, result) => {
              if (!err) {
                self.syncEvents(tokenId, result);
                result.forEach((withdrawEvent) => {
                  this.setEventLoadingIndicatorStatus(withdrawEvent.transactionHash, true);
                });
                Session.set('loadingWrapHistory', false);
              }
              token.Withdrawal({who: address}, { fromBlock: 'latest' }, (err2, result2) => {
                if (!err2) {
                  this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                  self.syncEvent(tokenId, result2);
                }
              });
            });
          }
        }
      });
    });
  }

  prepareRowGNT(event, token, type, to) {
    const row = {
      blockNumber: event.blockNumber,
      transactionHash: event.transactionHash,
      timestamp: null,
      token,
      type,
      from: Session.get('address'),
      to,
      amount: event.args.value.toNumber(),
    };

    return row;
  }

  watchGNTTokenEvents(latestBlock) {
    const self = this;
    Dapple.getToken('GNT', (errorGNT, GNT) => {
      if (!errorGNT) {
        Dapple.getToken('W-GNT', (errorWGNT, WGNT) => {
          if (!errorWGNT) {
            WGNT.getBroker.call((errorBroker, broker) => {
              if (!errorBroker && broker !== '0x0000000000000000000000000000000000000000') {
                GNT.Transfer({ from: broker, to: WGNT.address }, {
                  fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
                }).get((error, result) => {
                  if (!error) {
                    const rows = [];
                    for (let i = 0; i < result.length; i++) {
                      rows[i] = self.prepareRowGNT(result[i],
                                                  Dapple.getTokenByAddress(WGNT.address),
                                                  'deposit',
                                                  WGNT.address);
                      this.setEventLoadingIndicatorStatus(result[i].transactionHash, true);
                    }
                    super.batchInsert(rows, () => {});
                    Session.set('loadingWrapHistory', false);
                  }
                  GNT.Transfer({ from: broker, to: WGNT.address },
                  { fromBlock: 'latest' }, (error2, result2) => {
                    if (!error2) {
                      const row = self.prepareRowGNT(result2,
                                                    Dapple.getTokenByAddress(WGNT.address),
                                                    'deposit',
                                                    WGNT.address);
                      this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                      super.insert(row);
                    }
                  });
                });

                GNT.Transfer({ from: WGNT.address, to: Session.get('address') }, {
                  fromBlock: latestBlock - (Session.get('AVGBlocksPerDay') * 7), // Last 7 days
                }).get((error, result) => {
                  if (!error) {
                    const rows = [];
                    for (let i = 0; i < result.length; i++) {
                      rows[i] = self.prepareRowGNT(result[i],
                                                  Dapple.getTokenByAddress(WGNT.address),
                                                  'withdrawal',
                                                  Session.get('address'));
                      this.setEventLoadingIndicatorStatus(result[i].transactionHash, true);
                    }
                    super.batchInsert(rows, () => {});
                    Session.set('loadingWrapHistory', false);
                  }
                  GNT.Transfer({ from: WGNT.address, to: Session.get('address') },
                  { fromBlock: 'latest' }, (error2, result2) => {
                    if (!error2) {
                      const row = self.prepareRowGNT(result2,
                                                    Dapple.getTokenByAddress(WGNT.address),
                                                    'withdrawal',
                                                    Session.get('address'));
                      this.setEventLoadingIndicatorStatus(result2.transactionHash, true);
                      super.insert(row);
                    }
                  });
                });
              }
            });
          }
        });
      }
    });
  }
}

export default new TokenEventCollection(null);

import { Mongo } from 'meteor/mongo';
import { Session } from 'meteor/session';
import { Dapple } from 'meteor/makerotc:dapple';
import { BigNumber } from 'meteor/ethereum:web3';

class LimitsCollection extends Mongo.Collection {
  // Sync token sell limits asynchronously
  sync() {
    function getMinSell(sellToken) {
      const sellTokenAddress = Dapple.getTokenAddress(sellToken);

      return new Promise((resolve, reject) => {
        Dapple['maker-otc'].objects.otc.getMinSell(sellTokenAddress, (error, amount) => {
          if (!error) {
            resolve([sellToken, amount]);
          } else {
            reject(error);
          }
        });
      });
    }

    const promises = Dapple.getTokens()
      .map((token) => getMinSell(token))
      .map((promise) => {
        promise.then((tokenAndAmount) => {
          const token = tokenAndAmount[0];
          const amount = tokenAndAmount[1];
          super.upsert(token, { $set: { limit: amount.toString() } });
        });
      });

    Promise.all(promises).then(() => {
      Session.set('limitsLoaded', true);
    });
  }

  limitForToken(token) {
    const record = super.findOne(token);
    return record ? new BigNumber(record.limit) : new BigNumber(0);
  }
}

export default new LimitsCollection(null);

import { Mongo } from 'meteor/mongo';
import { Session } from 'meteor/session';
import { BigNumber } from 'meteor/ethereum:web3';
import { Dapple, web3Obj } from 'meteor/makerotc:dapple';
import { _ } from 'meteor/underscore';
import { $ } from 'meteor/jquery';
import { moment } from 'meteor/momentjs:moment';

import Transactions from '/imports/api/transactions';
import { formatError } from '/imports/utils/functions';

import { convertToTokenPrecision, convertTo18Precision } from '/imports/utils/conversion';

const Offers = new Mongo.Collection(null);
const Trades = new Mongo.Collection(null);
const IndividualTrades = new Mongo.Collection(null);

const Status = {
  PENDING: 'pending',
  CONFIRMED: 'confirmed',
  CANCELLED: 'cancelled',
  BOUGHT: 'bought',
  OPEN: 'open',
  CLOSED: 'closed',
};

const BUY_GAS = 1000000;
const CANCEL_GAS = 1000000;

const TRADES_LIMIT = 0;
Session.set('lastTradesLimit', TRADES_LIMIT);

const OFFER_LIMIT = 0;
Session.set('orderBookLimit', OFFER_LIMIT);

const helpers = {
  volume(currency) {
    let volume = '0';
    if (this.buyWhichToken === currency) {
      volume = this.buyHowMuch;
    } else if (this.sellWhichToken === currency) {
      volume = this.sellHowMuch;
    }
    return volume;
  },
  type() {
    const baseCurrency = Session.get('baseCurrency');
    let type = '';
    if (this.buyWhichToken === baseCurrency) {
      type = 'bid';
    } else if (this.sellWhichToken === baseCurrency) {
      type = 'ask';
    }
    return type;
  },
  price() {
    const quoteCurrency = Session.get('quoteCurrency');
    const baseCurrency = Session.get('baseCurrency');
    let price = '0';
    if (this.buyWhichToken === quoteCurrency && this.sellWhichToken === baseCurrency) {
      price = new BigNumber(this.buyHowMuch).div(new BigNumber(this.sellHowMuch));
    } else if (this.buyWhichToken === baseCurrency && this.sellWhichToken === quoteCurrency) {
      price = new BigNumber(this.sellHowMuch).div(new BigNumber(this.buyHowMuch));
    }
    return price;
  },
};

function logTakeToTrade(logTake) {
  const buyWhichToken = Dapple.getTokenByAddress(logTake.args.buy_gem);
  const sellWhichToken = Dapple.getTokenByAddress(logTake.args.pay_gem);

  if (buyWhichToken && sellWhichToken && !logTake.removed) {
    return {
      buyWhichToken_address: logTake.args.buy_gem,
      buyWhichToken,
      sellWhichToken_address: logTake.args.pay_gem,
      sellWhichToken,
      buyHowMuch: convertTo18Precision(logTake.args.give_amt.toString(10), buyWhichToken),
      sellHowMuch: convertTo18Precision(logTake.args.take_amt.toString(10), sellWhichToken),
      timestamp: logTake.args.timestamp.toNumber(),
      transactionHash: logTake.transactionHash,
      issuer: logTake.args.maker,
      counterParty: logTake.args.taker,
    };
  }
  return false;
}

function getBlockNumberOfTheMostRecentBlock() {
  return Offers.getBlock('latest').then((block) => block.number);
}

function fetchIssuedTradesFor(address) {
  return new Promise((resolve, reject) => {
    Dapple['maker-otc'].objects.otc.LogTake({ maker: address }, {
      fromBlock: Dapple['maker-otc'].environments[Dapple.env].otc.blockNumber,
      toBlock: 'latest',
    }).get((error, logTakes) => {
      if (!error) {
        for (let i = 0; i < logTakes.length; i++) {
          const trade = logTakeToTrade(logTakes[i]);
          const eventLogIndex = logTakes[i].logIndex;
          if (trade) {
            const uniqueId = trade.transactionHash + eventLogIndex;
            IndividualTrades.upsert(uniqueId, trade);
          }
        }
        resolve();
      } else {
        // TODO: Display this to the user in a fixed error display panel
        console.debug('Cannot fetch issued trades');
        reject();
      }
    });
  });
}
function fetchAcceptedTradesFor(address) {
  return new Promise((resolve, reject) => {
    Dapple['maker-otc'].objects.otc.LogTake({ taker: address }, {
      fromBlock: Dapple['maker-otc'].environments[Dapple.env].otc.blockNumber,
      toBlock: 'latest',
    }).get((error, logTakes) => {
      if (!error) {
        for (let i = 0; i < logTakes.length; i++) {
          const currentTrade = logTakes[i].args;

          // We handle those scenario when we are filtering events base on maker property
          if (currentTrade.maker !== currentTrade.taker) {
            const trade = logTakeToTrade(logTakes[i]);
            const eventLogIndex = logTakes[i].logIndex;
            if (trade) {
              const uniqueId = trade.transactionHash + eventLogIndex;
              IndividualTrades.upsert(uniqueId, trade);
            }
          }
        }
        resolve();
      } else {
        // TODO: Display this to the user in a fixed error display panel
        console.debug('Cannot fetch accepted trades');
        reject();
      }
    });
  });
}

function listenForNewTradesOf(address) {
  getBlockNumberOfTheMostRecentBlock().then((latestBlock) => {
    Dapple['maker-otc'].objects.otc.LogTake({ maker: address },
      { fromBlock: latestBlock + 1 }, (error, logTake) => {
        if (!error) {
          const trade = logTakeToTrade(logTake);

          if (trade) {
            IndividualTrades.upsert(trade.transactionHash, trade);
          }
        }
      });
  });
}
function listenForAcceptedTradesOf(address) {
  getBlockNumberOfTheMostRecentBlock().then((latestBlock) => {
    Dapple['maker-otc'].objects.otc.LogTake({ taker: address },
      { fromBlock: latestBlock + 1 }, (error, logTake) => {
        if (!error) {
          if (logTake.args.maker !== logTake.args.taker) {
            const trade = logTakeToTrade(logTake);

            if (trade) {
              IndividualTrades.upsert(trade.transactionHash, trade);
            }
          }
        }
      });
  });
}
function listenForNewSortedOrders() {
  Dapple['maker-otc'].objects.otc.LogSortedOffer((err, result) => {
    if (!err) {
      const id = result.args.id.toNumber();
      Offers.syncOffer(id);
      Offers.remove(result.transactionHash);
    } else {
      console.debug('Error placing new sorted offer!', err);
    }
  });
}
function listenForFilledOrCancelledOrders() {
  /** When the order matching is activated we are using ItemUpdate only to listen for events
   * where a given order is getting cancelled or filled in ( in case of `buy` being enabled.*/
  Dapple['maker-otc'].objects.otc.LogItemUpdate((err, result) => {
    if (!err) {
      const idx = result.args.id;
      Dapple['maker-otc'].objects.otc.offers(idx.toNumber(), (error, data) => {
        if (!error) {
          const offer = Offers.findOne({ _id: idx.toString() });

          if (offer) {
            const [, , , , , active] = data;
            Offers.syncOffer(idx.toNumber());
            /**
             * When the order matching is enabled there is check on the contract side
             * before the creating new order.
             * It checks if the new order is about to match existing one. There are couple of scenarios:
             *
             *  - New order is filled in completely but the existing one is completed partially or completely
             *    = then no order is actually created on the blockchain so the UI has offer is transaction id only.
             *
             *  - New order is not filled in completely but fills the existing one completely
             *    = then new order is created with the remainings after the matching is done.
             *
             * Transaction hash of the event in the first case scenario, corresponds to the transaction hash,
             * used to store the offer on the client. In order to update the UI accordingly, when the first scenario is met
             * we used the transaction has to remove the new order from the collection.
             * */
            Offers.remove(result.transactionHash);
            if (!active) {
              Offers.remove(idx.toString());
            }
          }
        }
      });
    }
  });
}

Offers.syncedOffers = [];
window.Offers = Offers;

Offers.helpers(_.extend(helpers, {
